587	/// Borrowing iterator over a [`SortedList`] in ascending order.
588	pub struct Iter<'a, T> {
589	    inner: std::iter::Flatten<std::slice::Iter<'a, Vec<T>>>,
590	    remaining: usize,
591	}
592	
593	impl<'a, T> Iterator for Iter<'a, T> {
594	    type Item = &'a T;
595	
596	    fn next(&mut self) -> Option<Self::Item> {
597	        let item = self.inner.next();
598	        if item.is_some() {
599	            self.remaining -= 1;
600	        }
601	        item
602	    }
603	
604	    fn size_hint(&self) -> (usize, Option<usize>) {
605	        (self.remaining, Some(self.remaining))
606	    }
607	}
608	
609	impl<'a, T> DoubleEndedIterator for Iter<'a, T> {
610	    fn next_back(&mut self) -> Option<Self::Item> {
611	        let item = self.inner.next_back();
612	        if item.is_some() {
613	            self.remaining -= 1;
614	        }
615	        item
616	    }
617	}
618	
619	impl<'a, T> ExactSizeIterator for Iter<'a, T> {}
620	
621	impl<'a, T> IntoIterator for &'a SortedList<T> {
622	    type Item = &'a T;
623	    type IntoIter = Iter<'a, T>;
624	
625	    fn into_iter(self) -> Self::IntoIter {
626	        self.iter()
627	    }
628	}
629	
630	impl<T> IntoIterator for SortedList<T> {
631	    type Item = T;
632	    type IntoIter = std::vec::IntoIter<T>;
633	
634	    fn into_iter(self) -> Self::IntoIter {
635	        self.into_vec().into_iter()
636	    }
637	}
