176	    /// Values present in `self` but not in `other`.
177	    pub fn difference_with(&self, other: &SortedSet<T>) -> SortedSet<T>
178	    where
179	        T: Clone,
180	    {
181	        let mut merged = Vec::with_capacity(self.len());
182	        self.merge_walk(other, |ordering| ordering == Ordering::Less, false, &mut merged);
183	        SortedSet::from_sorted_unique(merged, self.load_factor())
184	    }
185	
186	    /// Values present in exactly one of `self` and `other`.
187	    pub fn symmetric_difference_with(&self, other: &SortedSet<T>) -> SortedSet<T>
188	    where
189	        T: Clone,
190	    {
191	        let mut merged = Vec::with_capacity(self.len() + other.len());
192	        self.merge_walk(other, |ordering| ordering != Ordering::Equal, true, &mut merged);
193	        SortedSet::from_sorted_unique(merged, self.load_factor())
194	    }
