196	    /// Walks both sorted sequences once, collecting the values that qualify.
197	    ///
198	    /// `keep` is asked about each value from `self` using how it compares to the
199	    /// current value from `other` (`Less` means "only in `self`", `Equal` means
200	    /// "in both"). `keep_other_only` decides whether values found solely in
201	    /// `other` are collected.
202	    fn merge_walk<F>(
203	        &self,
204	        other: &SortedSet<T>,
205	        keep: F,
206	        keep_other_only: bool,
207	        out: &mut Vec<T>,
208	    ) where
209	        T: Clone,
210	        F: Fn(Ordering) -> bool,
211	    {
212	        let mut left = self.iter().peekable();
213	        let mut right = other.iter().peekable();
214	        loop {
215	            // Decide first so the `peek` borrows end before we advance either side.
216	            let step = match (left.peek(), right.peek()) {
217	                (Some(a), Some(b)) => Some(a.cmp(b)),
218	                (Some(_), None) => Some(Ordering::Less),
219	                (None, Some(_)) => Some(Ordering::Greater),
220	                (None, None) => None,
221	            };
222	            match step {
223	                None => return,
224	                Some(Ordering::Less) => {
225	                    let a = left.next().expect("just peeked");
226	                    if keep(Ordering::Less) {
227	                        out.push(a.clone());
228	                    }
229	                }
230	                Some(Ordering::Greater) => {
231	                    let b = right.next().expect("just peeked");
232	                    if keep_other_only {
233	                        out.push(b.clone());
234	                    }
235	                }
236	                Some(Ordering::Equal) => {
237	                    let a = left.next().expect("just peeked");
238	                    right.next();
239	                    if keep(Ordering::Equal) {
240	                        out.push(a.clone());
241	                    }
242	                }
243	            }
244	        }
245	    }
