//! Throwaway audit harness: verifies the positional index tree bit-for-bit
//! against a fresh rebuild after every single mutation.
#![cfg(test)]

use super::sorted_list::SortedList;
use std::fmt::Debug;

/// Recompute what build_index() *would* produce for the current sublists,
/// independently of the incremental updates, and compare.
fn check<T: Ord + Clone + Debug>(list: &SortedList<T>, model: &[T], tag: &str) {
    let (lists_lens, index, offset, len, load) = list.debug_state();

    assert_eq!(len, model.len(), "{tag}: len");
    assert_eq!(list.to_vec(), model.to_vec(), "{tag}: contents");
    assert_eq!(lists_lens.iter().sum::<usize>(), len, "{tag}: sublist lens sum != len");
    for (i, l) in lists_lens.iter().enumerate() {
        assert!(*l > 0, "{tag}: sublist {i} EMPTY (lens={lists_lens:?})");
        assert!(*l <= 2 * load, "{tag}: sublist {i} len {l} > 2*load");
    }

    // Reference construction, straight from the documented layout.
    let (want_index, want_offset) = reference_index(&lists_lens);
    assert_eq!(
        (index.clone(), offset),
        (want_index.clone(), want_offset),
        "{tag}: index/offset STALE. lens={lists_lens:?} got_off={offset} want_off={want_offset}"
    );

    if !index.is_empty() {
        assert_eq!(index[0], len, "{tag}: root != len");
        for (pos, l) in lists_lens.iter().enumerate() {
            assert_eq!(index[offset + pos], *l, "{tag}: leaf {pos} wrong");
        }
        assert_eq!(index.len(), offset + lists_lens.len(), "{tag}: index length");
        // Every internal node equals the sum of its (in-range) children.
        for node in 0..offset {
            let l = 2 * node + 1;
            let r = 2 * node + 2;
            let sum = index.get(l).copied().unwrap_or(0) + index.get(r).copied().unwrap_or(0);
            assert_eq!(index[node], sum, "{tag}: node {node} != children sum");
        }
    }

    // Positional access at every rank, plus one past the end.
    for (rank, expected) in model.iter().enumerate() {
        assert_eq!(list.get(rank), Some(expected), "{tag}: get({rank})");
    }
    assert_eq!(list.get(model.len()), None, "{tag}: get(len)");
}

/// Reference implementation of the documented row layout.
fn reference_index(row0: &[usize]) -> (Vec<usize>, usize) {
    if row0.is_empty() {
        return (Vec::new(), 0);
    }
    if row0.len() == 1 {
        return (row0.to_vec(), 0);
    }
    let mut row1: Vec<usize> = row0.chunks(2).map(|c| c.iter().sum()).collect();
    if row1.len() == 1 {
        let mut v = row1;
        v.extend_from_slice(row0);
        return (v, 1);
    }
    let size = row1.len().next_power_of_two();
    row1.resize(size, 0);
    let mut rows = vec![row0.to_vec(), row1];
    while rows.last().unwrap().len() > 1 {
        let r: Vec<usize> = rows.last().unwrap().chunks(2).map(|c| c.iter().sum()).collect();
        rows.push(r);
    }
    let mut out = Vec::new();
    for r in rows.into_iter().rev() {
        out.extend(r);
    }
    (out, size * 2 - 1)
}

fn check_ranks(list: &SortedList<i64>, model: &[i64], tag: &str) {
    let lo = model.first().copied().unwrap_or(0) - 2;
    let hi = model.last().copied().unwrap_or(0) + 2;
    for probe in lo..=hi {
        let l = model.partition_point(|x| *x < probe);
        let r = model.partition_point(|x| *x <= probe);
        assert_eq!(list.bisect_left(&probe), l, "{tag}: bisect_left({probe})");
        assert_eq!(list.bisect_right(&probe), r, "{tag}: bisect_right({probe})");
        assert_eq!(list.contains(&probe), l != r, "{tag}: contains({probe})");
        assert_eq!(
            list.index_of(&probe),
            if l == r { None } else { Some(l) },
            "{tag}: index_of({probe})"
        );
        assert_eq!(list.count(&probe), r - l, "{tag}: count({probe})");
    }
}

