    for load in 1usize..=6 {
        let mut s = 0xDEADBEEFCAFEu64 ^ (load as u64 * 0x9E3779B9);
        let mut list = SortedList::with_load_factor(load);
        let mut model: Vec<i64> = Vec::new();
        for step in 0..3000u32 {
            let v = (lcg(&mut s) % 40) as i64;
            let action = lcg(&mut s) % 100;
            let tag = format!("mix load={load} step={step}");
            if model.is_empty() || action < 45 {
                list.insert(v);
                let at = model.partition_point(|x| *x <= v);
                model.insert(at, v);
            } else if action < 70 {
                let rank = (lcg(&mut s) as usize) % model.len();
                assert_eq!(list.pop(rank), Some(model.remove(rank)), "{tag} pop");
            } else if action < 90 {
                let present = model.contains(&v);
                assert_eq!(list.remove(&v), present, "{tag} remove");
                if present {
                    let at = model.iter().position(|x| *x == v).unwrap();
                    model.remove(at);
                }
            } else if action < 95 {
                let want = if model.is_empty() { None } else { Some(model.remove(0)) };
                assert_eq!(list.pop_first(), want, "{tag} pop_first");
            } else {
                let want = model.pop();
                assert_eq!(list.pop_last(), want, "{tag} pop_last");
            }
            check(&list, &model, &tag);
        }
        check_ranks(&list, &model, &format!("mix-ranks load={load}"));
    }
}

#[test]
fn t_drain_to_empty_and_regrow() {
    for load in 1usize..=4 {
        let mut list = SortedList::with_load_factor(load);
        let mut model: Vec<i64> = Vec::new();
        for round in 0..4 {
            for v in 0..25i64 {
                list.insert(v * (round + 1));
                let at = model.partition_point(|x| *x <= v * (round + 1));
                model.insert(at, v * (round + 1));
                check(&list, &model, &format!("regrow load={load} r={round} v={v}"));
            }
            while !model.is_empty() {
                assert_eq!(list.pop_last(), model.pop(), "drain load={load} r={round}");
                check(&list, &model, &format!("drain load={load} r={round}"));
            }
            assert!(list.is_empty());
        }
    }
}

#[test]
fn t_duplicates_heavy() {
    for load in 1usize..=4 {
        let mut list = SortedList::with_load_factor(load);
        let mut model: Vec<i64> = Vec::new();
        for i in 0..60i64 {
            let v = i % 3;
            list.insert(v);
            let at = model.partition_point(|x| *x <= v);
            model.insert(at, v);
            check(&list, &model, &format!("dup load={load} i={i}"));
        }
        check_ranks(&list, &model, &format!("dup-ranks load={load}"));
        for i in 0..60 {
