// ---- branch coverage instrumentation ----
use std::sync::atomic::{AtomicUsize, Ordering as AOrd};
pub static HITS: [AtomicUsize; 16] = [
    AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0),
    AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0),
    AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0),
    AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0), AtomicUsize::new(0),
];
pub fn hit(which: usize, aux: usize) {
    HITS[which].fetch_add(1, AOrd::Relaxed);
    // Branch 0 claims "only possible with a single, now-empty sublist".
    if which == 0 {
        assert_eq!(aux, 1, "branch0 reached with {aux} sublists, not 1!");
    }
    // Branch 4: merge branch entered with an emptied sublist.
    if which == 4 {
        HITS[8].fetch_add(1, AOrd::Relaxed);
    }
    if which == 7 {
        assert_eq!(aux, 2, "row1-collapse reached with row0.len()={aux}, not 2!");
    }
}

#[test]
fn zz_report_branch_coverage() {
    // Run a workload that should light up every branch, then report.
    for load in [1usize, 2, 3, 4] {
        let mut s = 0x51ED_2701u64 ^ load as u64;
        let mut list = SortedList::with_load_factor(load);
        let mut model: Vec<i64> = Vec::new();
        for _ in 0..30_000u32 {
            let v = (lcg(&mut s) % 60) as i64;
            if model.is_empty() || lcg(&mut s) % 2 == 0 {
                list.insert(v);
                let at = model.partition_point(|x| *x <= v);
                model.insert(at, v);
            } else {
                let rank = (lcg(&mut s) as usize) % model.len();
                assert_eq!(list.pop(rank), Some(model.remove(rank)));
            }
        }
        while !model.is_empty() {
            assert_eq!(list.pop(0), Some(model.remove(0)));
        }
    }
    let names = [
        "delete_at: sub_len==0 fast branch (single sublist emptied)",
        "delete_at: incremental index decrement",
        "delete_at: merge branch with pos==0",
        "delete_at: merge branch with pos>0",
        "delete_at: merge branch entered with an EMPTY sublist",
        "expand: split with index already empty",
        "expand: split with index non-empty (index cleared)",
