1	//! A sorted map keyed by any `Ord` type, layered on [`SortedList`].
2	//!
3	//! Entries are stored as key/value pairs ordered by key alone, so the list's
4	//! binary searches double as key lookups.
5	
6	use std::cmp::Ordering;
7	use std::fmt;
8	
9	// Relative path: see the note in `sorted_set`.
10	use super::sorted_list::{SortedList, DEFAULT_LOAD_FACTOR};
11	
12	/// A key/value pair ordered solely by its key.
13	struct Entry<K, V> {
14	    key: K,
15	    value: V,
16	}
17	
18	impl<K: Ord, V> PartialEq for Entry<K, V> {
19	    fn eq(&self, other: &Self) -> bool {
20	        self.key == other.key
21	    }
22	}
23	
24	impl<K: Ord, V> Eq for Entry<K, V> {}
25	
26	impl<K: Ord, V> PartialOrd for Entry<K, V> {
27	    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
28	        Some(self.cmp(other))
29	    }
30	}
31	
32	impl<K: Ord, V> Ord for Entry<K, V> {
33	    fn cmp(&self, other: &Self) -> Ordering {
34	        self.key.cmp(&other.key)
35	    }
36	}
37	
38	impl<K: Clone, V: Clone> Clone for Entry<K, V> {
39	    fn clone(&self) -> Self {
40	        Entry {
41	            key: self.key.clone(),
42	            value: self.value.clone(),
43	        }
44	    }
45	}
46	
47	/// A map whose keys are kept in ascending order.
48	pub struct SortedDict<K, V> {
49	    entries: SortedList<Entry<K, V>>,
50	}
51	
52	impl<K, V> SortedDict<K, V> {
53	    /// Creates an empty map using [`DEFAULT_LOAD_FACTOR`].
54	    pub fn new() -> Self {
55	        Self::with_load_factor(DEFAULT_LOAD_FACTOR)
56	    }
57	
58	    /// Creates an empty map with an explicit load factor.
59	    pub fn with_load_factor(load: usize) -> Self {
60	        SortedDict {
61	            entries: SortedList::with_load_factor(load),
62	        }
63	    }
64	
65	    /// Number of entries in the map.
66	    pub fn len(&self) -> usize {
67	        self.entries.len()
68	    }
69	
70	    /// Returns `true` when the map holds no entries.
71	    pub fn is_empty(&self) -> bool {
72	        self.entries.is_empty()
73	    }
74	
75	    /// Removes every entry.
76	    pub fn clear(&mut self) {
77	        self.entries.clear();
78	    }
79	
80	    /// Iterates over the entries in ascending key order.
81	    pub fn iter(&self) -> impl DoubleEndedIterator<Item = (&K, &V)> + '_ {
82	        self.entries.iter().map(|entry| (&entry.key, &entry.value))
83	    }
84	
85	    /// Iterates over the keys in ascending order.
86	    pub fn keys(&self) -> impl DoubleEndedIterator<Item = &K> + '_ {
87	        self.entries.iter().map(|entry| &entry.key)
88	    }
89	
90	    /// Iterates over the values, ordered by their keys.
91	    pub fn values(&self) -> impl DoubleEndedIterator<Item = &V> + '_ {
92	        self.entries.iter().map(|entry| &entry.value)
93	    }
94	
95	    /// Returns the entry at rank `idx` in key order.
96	    pub fn get_index(&self, idx: usize) -> Option<(&K, &V)> {
97	        self.entries
98	            .get(idx)
99	            .map(|entry| (&entry.key, &entry.value))
100	    }
101	
102	    /// Returns the entry with the smallest key.
103	    pub fn first_key_value(&self) -> Option<(&K, &V)> {
104	        self.entries.first().map(|e| (&e.key, &e.value))
105	    }
106	
107	    /// Returns the entry with the largest key.
108	    pub fn last_key_value(&self) -> Option<(&K, &V)> {
109	        self.entries.last().map(|e| (&e.key, &e.value))
110	    }
111	
112	    /// Removes and returns the entry with the smallest key.
113	    pub fn pop_first(&mut self) -> Option<(K, V)> {
114	        self.entries.pop_first().map(|e| (e.key, e.value))
115	    }
116	
117	    /// Removes and returns the entry with the largest key.
118	    pub fn pop_last(&mut self) -> Option<(K, V)> {
119	        self.entries.pop_last().map(|e| (e.key, e.value))
120	    }
121	}
122	
123	impl<K: Ord, V> SortedDict<K, V> {
124	    /// Inserts a key/value pair, returning the previous value for that key.
125	    pub fn insert(&mut self, key: K, value: V) -> Option<V> {
126	        self.entries
127	            .insert_or_replace(Entry { key, value })
128	            .map(|old| old.value)
129	    }
130	
131	    /// Returns the value stored under `key`.
132	    pub fn get(&self, key: &K) -> Option<&V> {
133	        self.entries
134	            .find_by(|entry| entry.key.cmp(key))
135	            .map(|entry| &entry.value)
136	    }
137	
138	    /// Returns a mutable reference to the value stored under `key`.
139	    pub fn get_mut(&mut self, key: &K) -> Option<&mut V> {
140	        self.entries
141	            .find_mut_by(|entry| entry.key.cmp(key))
142	            .map(|entry| &mut entry.value)
143	    }
144	
145	    /// Returns `true` when `key` is present.
146	    pub fn contains_key(&self, key: &K) -> bool {
147	        self.entries
148	            .find_by(|entry| entry.key.cmp(key))
149	            .is_some()
150	    }
151	
152	    /// Removes `key`, returning its value.
153	    pub fn remove(&mut self, key: &K) -> Option<V> {
154	        self.entries
155	            .remove_by(|entry| entry.key.cmp(key))
156	            .map(|entry| entry.value)
157	    }
158	
159	    /// Rank of the first key not less than `key`.
160	    pub fn bisect_left(&self, key: &K) -> usize {
161	        self.entries.bisect_left_by(|entry| entry.key.cmp(key))
162	    }
163	
164	    /// Rank of the first key greater than `key`.
165	    pub fn bisect_right(&self, key: &K) -> usize {
166	        self.entries.bisect_right_by(|entry| entry.key.cmp(key))
167	    }
168	}
169	
170	impl<K: Ord, V> FromIterator<(K, V)> for SortedDict<K, V> {
171	    fn from_iter<I: IntoIterator<Item = (K, V)>>(iter: I) -> Self {
172	        let mut dict = SortedDict::new();
173	        for (key, value) in iter {
174	            dict.insert(key, value);
175	        }
176	        dict
177	    }
178	}
179	
180	impl<K: Ord, V> Extend<(K, V)> for SortedDict<K, V> {
181	    fn extend<I: IntoIterator<Item = (K, V)>>(&mut self, iter: I) {
182	        for (key, value) in iter {
183	            self.insert(key, value);
184	        }
185	    }
186	}
187	
188	impl<K, V> Default for SortedDict<K, V> {
189	    fn default() -> Self {
190	        Self::new()
191	    }
192	}
193	
194	impl<K: Clone, V: Clone> Clone for SortedDict<K, V> {
195	    fn clone(&self) -> Self {
196	        SortedDict {
197	            entries: self.entries.clone(),
198	        }
199	    }
200	}
201	
202	impl<K: fmt::Debug, V: fmt::Debug> fmt::Debug for SortedDict<K, V> {
203	    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
204	        f.debug_map().entries(self.iter()).finish()
205	    }
206	}
207	
