209	mod tests {
210	    use super::*;
211	
212	    #[test]
213	    fn insert_get_and_replace() {
214	        let mut dict: SortedDict<i32, &str> = SortedDict::with_load_factor(2);
215	        assert_eq!(dict.insert(3, "three"), None);
216	        assert_eq!(dict.insert(1, "one"), None);
217	        assert_eq!(dict.insert(2, "two"), None);
