#[test]
fn t_huge_leaf_count() {
    // load=1 => one element per sublist after a bulk rebuild, so L == n.
    // n = 100_000 gives row1 = 50_000 -> size = 65_536, offset = 131_071 and a
    // very ragged bottom row (100_000 leaves in a row sized for 131_072).
    for n in [65_535usize, 65_536, 65_537, 100_000, 131_071, 131_072, 131_073] {
        let mut list = SortedList::with_load_factor(1);
        let model: Vec<i64> = (0..n as i64).collect();
        list.extend_from(model.clone());
        let (lens, index, offset, len, _) = list.debug_state();
        assert_eq!(lens.len(), n, "L");
        assert_eq!(len, n);
        assert_eq!(index.len(), offset + n, "index len for n={n}");
        assert_eq!(index[0], n, "root for n={n}");
        for node in 0..offset {
            let s = index.get(2 * node + 1).copied().unwrap_or(0)
                + index.get(2 * node + 2).copied().unwrap_or(0);
            assert_eq!(index[node], s, "node {node} for n={n}");
        }
        // Every rank must resolve, including the last few (ragged tail).
        for rank in (0..n).step_by(7) {
            assert_eq!(list.get(rank), Some(&(rank as i64)), "get({rank}) n={n}");
        }
        for rank in n.saturating_sub(5)..n {
            assert_eq!(list.get(rank), Some(&(rank as i64)), "tail get({rank}) n={n}");
            assert_eq!(list.index_of(&(rank as i64)), Some(rank), "tail idx n={n}");
        }
        assert_eq!(list.get(n), None);
        assert_eq!(list.index_of(&0), Some(0));
        assert_eq!(list.bisect_left(&(n as i64)), n);
        assert_eq!(list.bisect_right(&-1), 0);
    }
}
EOF
